------------ import ------------
local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local UIEventProxy = CS.Engine.UI.UIEventProxy
local KTool = CS.Engine.Lib.KTool
local UINavigationBarRoot = CS.UINavigationBarRoot
local UIModule = CS.Engine.UI.UIModule
local CDTimerModule = CS.Engine.Modules.CDTimerModule.GetInstance()
local cs_coroutine      = require('XLua.cs_coroutine')
local friendComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FriendComponent)
------------ import ------------

------------ define ------------

------------ define ------------


---@class FriendInvitationReceive
---@field UIEffectCaptured               	UnityEngine.RectTransform
---@field BtnReceive                    	UnityEngine.UI.Button
---@field BtnCancel                     	UnityEngine.UI.Button
---@field Fill                          	UnityEngine.UI.Image
---@field TxtTime                       	TMPro.TextMeshProUGUI
---@field TxtContent                    	UnityEngine.UI.Text
---@field CommonPlayerHeadNode          	Engine.Modules.LuaBehaviour
local FriendInvitationReceive = Class("FriendInvitationReceive")
function FriendInvitationReceive:__init()
    self.data = nil

end

function FriendInvitationReceive:__delete()
    self.controller = nil
    self.data = nil
end

function FriendInvitationReceive:Awake()
    self.EventFriendPVPPromptBeCancelled = Events.AddListener(Constants.EventNames.FriendPVPPromptBeCancelled, Bind(self, self.FriendPVPBeCancelled))
    if isNull(self.CommonPlayerHeadNode.Env) then
        self.CommonPlayerHeadNode:Init()
    end
end

function FriendInvitationReceive:ShowInvitation()
    self.CommonPlayerHeadNode.Env:FreshAvatarFrame(self.data.avatar, self.data.avatarFrame)
    self.TxtContent.text = localize("<color=#ff2dc1>[_name_]</color>邀请您战斗...",{_name_ = self.data.name})
    self:StartLeftSecond(self.data.time)

end

---开始倒计时
function FriendInvitationReceive:StartLeftSecond(leftTime)
    self:StopTimer()
    self.timer = CDTimerModule:AddCD(1, function (count, id)
        if count == 0 then
            UIModule.BackDialog()
        end
        self.data.time = count
        self.TxtTime.text = count
        self.Fill.fillAmount = count / leftTime
    end, leftTime, true, true, true)
end

function FriendInvitationReceive:StopTimer()
    if not isNull(self.timer) then
        CDTimerModule:RemoveCD(self.timer)
        self.timer = nil
    end
end

function FriendInvitationReceive:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument
        if not isNull(argument.parameters) then
            self.data = argument.parameters.data
            SetButtonAction(self.BtnReceive, function()
                local screenId = UIModule.CurrentScreen.Argument.id
                if screenId == Constants.UITypeIds.UIMaidCoffeeEnterScene then
                    GameUtils.Toast(localize("在餐厅中无法接受好友切磋"))
                    return
                end
                --接受
                if friendComponent:HasPVPTeam() then
                    ---@type TeamComponent
                    local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
                    teamComponent:SetTeamReq(Constants.SpecialQuestId.FriendPVPId, function()
                        self.co_accept = cs_coroutine.start(function()
                            cs_coroutine.yield_return(UIModule.BackDialog())
                            argument.parameters.responseFunc()
                            friendComponent:ReplyInvite(1)
                        end)
                    end)
                else
                    -- 如果没有编队，先去编队
                    self.co_accept = cs_coroutine.start(function()
                        cs_coroutine.yield_return(UIModule.BackDialog())
                        argument.parameters.backFunc()
                        GameUtils.Toast(localize("您还没有编队，请先编个队吧"))
                        if not friendComponent:IsInPVPFormation() then
                            local closeHomeView = GameUtils.IsInMainHomeView() and {{id = Constants.UITypeIds.UIHomeView}} or nil
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = Constants.SpecialQuestId.FriendPVPId, teamIndex = 1 } }, closeHomeView)
                        end
                    end)
                end
            end)
            SetButtonAction(self.BtnCancel, function()--拒绝
                UIModule.BackDialog()
                argument.parameters.responseFunc()
                friendComponent:ReplyInvite(0)
            end)
            UIEventProxy.Create(self.UIEffectCaptured.gameObject).onPointerClick = function()
                UIModule.BackDialog()
                argument.parameters.backFunc()

            end

            -- 没有编队时显示空提示
            KTool.SetActive(self.BtnReceive.transform:Find("TextAccept"), friendComponent:HasPVPTeam())
            KTool.SetActive(self.BtnReceive.transform:Find("ImgBgEmpty"), not friendComponent:HasPVPTeam())

            self:ShowInvitation()
        end
    end))
    return coWait
end

---好友pvp邀请被取消
function FriendInvitationReceive:FriendPVPBeCancelled()
    CoStop(self.co_accept)
    UIModule.BackDialog()
end

function FriendInvitationReceive:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.FriendPVPPromptBeCancelled, self.EventFriendPVPPromptBeCancelled)
        self:StopTimer()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return FriendInvitationReceive